INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '34cf5b67-f467-4512-b8aa-cac2328362e6', NOW(), NOW(), 'amelia', 'Amelia, 2022', 'Белое', 'Соломенный, с зеленоватым оттенком', 'Кубань',
    '["Рислинг"]'::jsonb, 'Вино соломенного цвета с изящным зеленоватым оттенком выглядит свежо и элегантно. Его выразительный вкус сочетает высокую кислотность с лёгкостью и при этом глубиной, создавая гармоничный и живой характер. В основе вкусовой палитры лежат тона душистой груши, лимонной цедры и минеральные оттенки, формирующие чистый и освежающий профиль. Нежный аромат раскрывается постепенно: в первом носе доминируют классические бензольные ноты, затем проявляются нюансы запечённой айвы и тонкий намёк на зелёное яблоко, придавая букету сложность и утончённость.

Винификация при контролируемой температуре и выдержка вина на осадке с регулярным батонажем проводятся частично в стальных чанах (80%) и частично в барриках из французского дуба (20%). Созревание длится 4 месяца, затем вино бутилируется.

НАГРАДЫ: Лучшие российские вина 2025/2026, Simple Wine News; Серебро "Гид по российским винам" Артура Саркисяна и РБК, 2025', 'WINEMAFIA', 83.5, NULL,
    2022, NULL, 'Amelia 22_png.webp', 'catalog/Amelia 22_png.webp',
    1.20, 2.20, 4.50, 1.10,
    '["яблоко", "груша", "айва", "лимон", "дуб", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
