    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '64fc5659-3c93-482b-b3ca-e35858e92734', NOW(), NOW(), 'ballet-blanc', 'Ballet Blanc', 'Белое', 'Cветло-соломенный', 'Кубань',
    '["Рислинг", "Совиньон Блан", "Шардоне"]'::jsonb, 'Аромат: свежие ягоды и фрукты: яблоко, абрикос, зелёный крыжовник; полевые травы и весенние цветы.

Вкус: лёгкий, с освежающей кислотностью, солоноватый с минеральным финишем – мокрые камни и створки моллюсков.

Особенность винификации

Раздельная уборка и винификация каждого из сортов. Тщательная инспекция ягод. Настаивание в прессе для Рислинга и Совиньона Блана в течение четырёх часов, Шардоне — без настаивания. Отбор лучшего сока. Для Рислинга и Совиньона Блана брожение только в стали при температуре 18–19 градусов Цельсия. Для Шардоне 19–20 градусов Цельсия, частично в стали, частично в бургундский пьесах из французского дуба, 2-ой пассаж. В бочках проводится полная малолактика. Выдержка на осадке с регулярным батоннажем в течение 11 мес. Интенсивность батоннажей снижается по мере выдержки. Ассамбляж, оклейка и розлив с применением инертного газа. Отдых в бутылке более 3 мес перед началом оформления и продаж.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'балет блан.webp', 'catalog/балет блан.webp',
    1.20, 2.20, 4.50, 4.20,
    '["яблоко", "абрикос", "полевые травы", "дуб", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
