    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '51028f5c-efc4-4dd5-80ee-33a2b7131b88', NOW(), NOW(), 'abrau-dyurso-brut-dor-blanc-de-blancs-shardone-beloe-bryut-12', 'Brut d''Or Blanc de Blancs', 'Белое', 'Яркий и насыщенный соломенный цвет с сияющими золотыми бликами.', 'Кубань',
    '["Шардоне"]'::jsonb, 'Игра пузырьков тонкая, непрерывная, с мельчайшими жемчужными нитями. Аромат яркий и объемный. В первом носе чуть дымные и тостовые ноты, которые раскрываются сочными акцентами спелой алычи, хрустящего зеленого яблока и нежной пенки от варенья из желтых слив. Мягко звучит кремово-сливочный тон, напоминающий свежую бриошь и халву. Вкус яркий, объемный, с исключительно изящной структурой. Мягкая сливочная текстура идеально сбалансирована свежей, гармоничной кислотностью. Финал долгий, мягкий, с элегантным минеральным оттенком. Прекрасный аперитив.', 'Абрау-Дюрсо', 83.5, 'Брют',
    NULL, NULL, 'abrau-dyurso-brut-dor-blanc-de-blancs-shardone-igristoe-bryut-beloe-12.webp', 'catalog/abrau-dyurso-brut-dor-blanc-de-blancs-shardone-igristoe-bryut-beloe-12.webp',
    1.20, 2.20, 4.50, 4.20,
    '["зеленое яблоко", "яблоко", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
