INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'c42c9d4f-54eb-4aa7-8f6c-c0ca16604e4f', NOW(), NOW(), 'cantiani-cabernet-sauvignon-reserve-2024', 'Cantiani Cabernet Sauvignon Reserve, 2024', 'Красное', 'Насыщенно-рубиновый', 'Дагестан',
    '["Каберне Совиньон"]'::jsonb, 'Вино Cantiani Reserve проходит выдержку в бочках из благородного французского дуба в течение шести месяцев. За это время вино приобретает сложную структуру, развивает свои ароматические характеристики и достигает вершины вкуса. Вино становится многослойным, где фруктовые ноты переплетаются со «вторичными» (древесными) и «третичными» (при старении в бутылке) ароматами. Именно выдержанные в бочках вина чаще всего способны развиваться и в бутылке десятилетиями. Тираж 58 000 бутылок.

В букете выражены яркие сортовые оттенки винограда Каберне-Совиньон: черная смородина, фрукты: слива, ежевика, вишня, малина, а также древесные и пряные ноты. Вкус гармоничный, с легкой терпкостью и длительным бархатистым послевкусием', 'Шато АЛВИСА', 83.5, NULL,
