    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'aa9e4fd6-6781-460e-bbef-f15fff19ed06', NOW(), NOW(), 'chateau-tamagne-signature-kaberne', 'Chateau Tamagne Signature. Каберне', 'Красное', 'Темно-рубиновый с гранатовым оттенком', 'Кубань',
    '["Каберне Совиньон"]'::jsonb, 'Вкус сложный, с гармоничным сочетанием тонов черной смородины и чернослива, с легкими сафьяновыми нотами. Аромат полный, свежий, экстрактивный с тонами черной смородины и чернослива, на фоне благородного дуба.

Сбор винограда осуществляется на сахарах 21-23%. Переработка проводится по «красному способу», каждого сорта винограда по отдельности. После дробления винограда, полученную мезгу сульфитируют до 50 (свободная) и оправляют на брожение на чистых культурах дрожжей, в емкостях из нержавеющей стали при температуре до 23-25°С, с регулярным орошением «шапки» мезги. В ходе брожения осуществляется систематический контроль за температурой и количеством сброженных сахаров, а также состоянием микрофлоры. После брожения производится съем виноматериала с дрожжевого осадка и внесение чистой культуры бактерий для ЯМБ. После окончания яблочно-молочного брожения проводят открытую переливку с сульфитацией и купажированием виноматериала. Затем виноматериал направляют на выдержку. Выдержку производят в технологической таре, в том числе в дубовой, не менее 12 месяцев.
 
Выдержка в технологической таре, в том числе в дубовой таре, не менее 12 месяцев. После снятия с выдержки виноматериалов, осуществляют сбор производственного купажа.', 'Кубань-Вино', 83.5, NULL,
    NULL, NULL, 'ШТ_Signature_Cabernet_23.webp', 'catalog/ШТ_Signature_Cabernet_23.webp',
    1.20, 4.00, 3.00, 4.20,
    '["черная смородина", "чернослив", "яблоко", "дуб"]'::jsonb, '[]'::jsonb, 0.95
