INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'fa8a3a92-4ab0-4570-935b-0c2eac73af7c', NOW(), NOW(), 'cosaque-krasnaya-gorka', 'Cosaque', 'Красное', 'Рубиновый', 'Кубань',
    '["Каберне Совиньон", "Красностоп Золотовский", "Мерло", "Цимлянский черный"]'::jsonb, 'Аромат: сложный и яркий, в нём переплетаются, дополняя друг друга, оттенки спелой сочной вишни, ежевики, кофе, благородного дуба, тёплой вспаханной земли и лёгкие копчёные ноты.

Вкус: комплексный и сложный, с обилием спелых танинов, долгим и ярким вишнёво-ванильным послевкусием. С течением бутылочной выдержки вкусо-ароматический профиль дополняют ноты анималистики.

Особенность винификации

Ручной сбор. Винификация раздельная по каждому сорту. Двойная инспекция ягод. Деликатное гребнеотделение с получением целых ягод. Предферментационная мацерация в течение 5–7 дней, в зависимости от сорта, при температуре 8 градусов Цельсия. Техника винификации — комбинация ремонтажа и деликатного переворачивания «шапки» специальной боковой мешалкой. Брожение в стальном винификаторе, при температуре 30 градусов Цельсия — 7–8 дней, в зависимости от сорта, с последующей постферментационной мацерацией. Средняя продолжительность скин-контакта — 23 дня. Полная малолактика. Купажирование. Выдержка в новых тонно из французского дуба объёмом 500 литров в течение 12 месяцев — 50% от общего объёма. Остальные 50% выдерживаются 12 месяцев в новых барриках из французского, кавказского и иберийского дубов объёмом 225 литров. Ассамбляж. Кларификация. Стабилизация тартратов. Розлив с применением инертного газа и вакуумирования.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'казак.webp', 'catalog/казак.webp',
    1.20, 2.80, 3.00, 1.10,
    '["вишня", "ежевика", "дуб", "ваниль", "кофе"]'::jsonb, '["ваниль", "кофе"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
