    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'cff3e0d1-cd17-4578-ac6b-ad58b63481fb', NOW(), NOW(), 'grand-jete-cuvee', 'Grand Jete Cuvee', 'Белое', 'Светло-золотистый', 'Кубань',
    '["Пино Нуар", "Шардоне"]'::jsonb, 'Аромат: раскрывается оттенками белых фруктов, лимонной травы, свежего имбиря и слегка поджаренной бриоши.

Вкус: мягкое и обволакивающее. Сливочная текстура уравновешивается цитрусовой кислотностью, которая плавно переходит в долгое интригующее послевкусие.

Особенность винификации

Сбор урожая проводится исключительно вручную во второй декаде августа. Раздельная уборка и винификация каждого из сортов. Тщательная инспекция гроздей. Прессование винограда проводилось целыми гроздями, без гребнеотделения, как это принято в технологии создания игристых вин. Для вина используется только самотек и сок первого давления (cuvee) от Шардоне и Пино нуар. 10% от общего объема было сброжено и выдержано в дубовых бочках с полной малолактикой. 90% от объема - это выдержка и брожение в стали при контролируемой температуре. Ассамбляж. Вторичная ферментация и дальнейшая выдержка на осадке в бутылках не менее 36 месяцев.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'output_img_023.webp', 'catalog/output_img_023.webp',
    1.20, 2.20, 3.80, 4.20,
    '["лимон", "полевые травы", "дуб"]'::jsonb, '[]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
