    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '82367271-e04b-4eeb-a66e-a9e01439e036', NOW(), NOW(), 'naomi-2022', 'Naomi, 2022', 'Розовое', 'Ягодно-насыщенный барбарисовый', 'Кубань',
    '["Каберне Фран"]'::jsonb, 'Вино ягодно-насыщенного барбарисового цвета с свежим и звонким вкусом, который покоряет интенсивностью ягодных оттенков и приятной, освежающей кислотностью. В послевкусии проявляется лёгкая, изящная терпкость, придающая вину характер и завершённость. Аромат соблазнительный и яркий, наполненный нотами сочных красных ягод и нежными тонами тропических фруктов.

Полученное после деликатного прессования сусло ферментируется при контролируемой температуре около 14 °С. Далее вино выдерживается на тонком осадке на протяжении 3-4 месяцев. Батонаж проводится 1 раз в 2 недели. Перед бутилированием вино осветляется и фильтруется.

НАГРАДЫ: Серебро "Гид по российским винам" Артура Саркисяна и РБК, 2026;  Серебро "Гид по российским винам" Артура Саркисяна и РБК, 2025', 'WINEMAFIA', 83.5, NULL,
