    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'd397d579-57ea-4ff7-a287-f37811b6095a', NOW(), NOW(), 'nebbiolo', 'Nebbiolo', 'Красное', 'Гранатово-красный', 'Кубань',
    '["Неббиоло"]'::jsonb, 'Аромат: яркие оттенки малины, сухих цветов, выделанной кожи. Красиво дополняется тонами перечной мяты, экзотических пряностей и древесной смолы.

Вкус: объемная текстура, бархатистые танины, великолепный баланс между кислотностью и гастрономической сладостью. Объемное и элегантное одновременно. Финиш у вина яркий и длительный, с преобладанием в послевкусии оттенков ванили, кофе и сладких фиников.

Особенность винификации

Ручной сбор в первой декаде октября.
Предварительное охлаждение винограда, двойной триаж, полное гребнеотделение. Предферментационная мацерация в течение 5 дней при температуре +8 градусов Цельсия. Брожение при температуре 25-27 градусов Цельсия. Техника винификации - комбинация ремонтажа и делестажа.
Общая продолжительность скин-контакта 45 дней. ЯМБ прошло на мезге в стальном резервуаре. Деликатное прессование, выдержка в больших ботти из славонского и французского дуба в течение 25 месяцев.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'неббиоло.webp', 'catalog/неббиоло.webp',
    1.20, 2.80, 3.00, 1.10,
    '["малина", "дуб", "ваниль", "кофе", "перец", "кожа"]'::jsonb, '["ваниль", "кофе", "перец"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
