INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'cad8f25d-7d32-4a12-b4ae-e30800f5160d', NOW(), NOW(), 'pinot-noir-2024-one-barrel-by-dmitry-maslov-pino-nuar-2024-uan-barrel-dmitrij-maslov', 'Pinot Noir 2024 One Barrel by Dmitry Maslov (Пино Нуар 2024 Уан Баррел Дмитрий Маслов)', 'Красное', 'рубиновый', 'Крым',
    '["Пино Нуар"]'::jsonb, 'Преобладает элегантный и яркий фруктовый аромат красных ягод брусники и кизила. Легкотелое, мягкое с лёгким и спелым танином. Средняя кислотность.  Pinot Noir One Barrel 2024, тираж 1956 бутылок

Урожай Пино Нуар, клон #375, для второго винтажа с виноградника в коммуне Айвовое на западе Бахчисарайского района, в долине реки Кача был собран в конце августа. Этот редкий клон Пино Нуар культивируется в Бургундии, в единственном «тихом» апеласьоне Кото Шампенуа в Шампани, где из него производят красные вина, и в Лангедоке. Он показал в жарком и сухом 2024 отличную фенольную зрелость и алкоголь получился 12%.

У вина «южный профиль в северной упаковке»,  кислотность выше среднего, тело среднее минус, в основе элегантный и яркий фруктовый аромат красных ягод брусники и кизила, мягкая  танинная структура, длина, и возможность потребления молодым, а также отличный потенциал. 

Технология производства: гребнеотделение, 7 дней мацерации, 70% целыми ягодами, 30% - дробление, низкая t ферментации, без пижажей только ремонтаж, 7 бочек по 225 литров, 4 заливка, выдержка 10 месяцев. 

Фирменная этикетка из обоев выпуска 1988 года Пермского целлюлозно-бумажного комбината. Оттенок 65. На обоях тоже попадаются в тему мелкие ягодки.', 'One Barrel (Уан Баррел)', 83.5, NULL,
    2024, NULL, 'IMG-20250829-WA0033 (1).webp', 'catalog/IMG-20250829-WA0033 (1).webp',
    1.20, 4.00, 2.40, 4.20,
    '["брусника"]'::jsonb, '[]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
