INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '5ce83e7e-2dbb-420b-a2e0-08298a48774c', NOW(), NOW(), 'riesling-dva-petra-2022', 'Riesling Два Петра 2022', 'Белое', 'Бледно-лимонный', 'Крым',
    '["Рислинг"]'::jsonb, 'Вкус: легкий, свежий и минеральный вкус с хорошо интегрированной кислотностью. Гармоничная структура с оттенками зеленого яблока и косточки абрикоса в послевкусии. Баланс и точность — ключевые черты этого вина.

Аромат: тонкий и многослойный, с акцентами белых цветов, зеленого яблока и косточковых фруктов. Легкие нюансы цитрусов, молодой травы и характерная для Рислинга бензольная нота придают аромату узнаваемую сортовую элегантность.

"Два Петра" Рислинг — белое сухое вино, созданное на крымской винодельне, расположенной в районе Феодосии. Выполненное из винограда сорта Рислинг урожая 2022 года, это вино отражает особенности южного терруара и философию авторского подхода к производству.

Бережная переработка урожая начинается с отбора и прессования, после чего сусло сбраживается при контролируемой температуре, что позволяет сохранить естественную свежесть. Вино проходит легкую фильтрацию и разливается без выдержки, сразу после стабилизации.

Элегантное, сбалансированное и чистое по стилю, оно хорошо подходит как для повседневной подачи, так и для гастрономических сочетаний. Идеально раскрывается при подаче охлажденным.

"Два Петра" Рислинг было удостоено бронзовой медали на международной выставке "Продэкспо-2025" в Москве. Эта награда подтверждают стабильное качество и высокую оценку вина со стороны профессионального дегустационного сообщества.', 'Два Петра', 83.5, 'Сухое',
    2022, NULL, 'Шардоне-no-bg-preview (carve.photos).webp', 'catalog/Шардоне-no-bg-preview (carve.photos).webp',
    1.20, 2.20, 4.50, 4.20,
    '["зеленое яблоко", "яблоко", "абрикос", "мед", "белые цветы", "полевые травы", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
