    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '25938c5b-d6bd-4079-a4f5-419fd8a6eb08', NOW(), NOW(), 'esse-rose-cuvee-prestige-pino-nuar-rozovoe-bryut-13', 'Rose Cuvee Prestige', 'Розовое', 'Нежный бледно-розовый цвет с переливами розового золота.', 'Крым',
    '["Пино Нуар"]'::jsonb, 'Тончайшая игра пузырьков, выстраивающихся в изящные непрерывные нити. Аромат раскрывается акварельными ягодными нотами: спелая красная смородина, воздушный мусс из лесной земляники, легкие акценты сушеной малины и нежная пенка вишневого варенья. Фоном звучат тонкие теплые оттенки яблочных чипсов. Вкус утонченный, свежий, с изящной кислотностью и шелковистой игрой пузырьков. Послевкусие легкое, освежающее, с ягодными обертонами. Прекрасный аперитив.', 'ESSE', 83.5, NULL,
