    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '7fca4cdf-6a67-47e7-a97e-3db7511adf71', NOW(), NOW(), 'sacrum-bryut-beloe', 'Sacrum, брют, белое', 'Белое', 'Карамельно-золотистый', 'Кубань',
    '["Совиньон Блан"]'::jsonb, 'Вино карамельно-золотистого цвета привлекает тёплым, благородным оттенком. Во вкусе ощущается умеренная, гармоничная свежесть, на фоне которой ярко раскрываются тона спелой дыни, сочной груши и мягкого абрикоса. Аромат наполнен оттенками зрелых жёлтых фруктов с лёгкими цитрусовыми акцентами. По мере аэрации букет становится глубже и сложнее, проявляя ноты корочки яблока с гриля и деликатные табачные нюансы, придающие вину элегантность и характер.

Изготовленное по классической технологии и выдержанное не менее 12 месяцев на осадке. Виноград собирается вручную. Технология производства включает краткую криомацерацию, выдержку не менее 3 месяцев сусла в американском дубе и полное яблочно-молочное брожение.

НАГРАДЫ: Лучшие российские игристые вина по версии Simple Wine News 2025/2026', 'WINEMAFIA', 83.5, 'Брют',
