) VALUES (
    'a64ceebb-9ba0-428b-8892-b0c8b2922242', NOW(), NOW(), 'abrau-dyurso-udelnoe-vedomstvo-imperatorskoe-beloe-bryut', 'Абрау Дюрсо Удельное Ведомство Императорское белое брют', 'Белое', 'Светло-соломенный с тонким зеленоватым оттенком', 'Кубань',
    '["Рислинг", "Совиньон Блан", "Шардоне"]'::jsonb, 'Великолепное вино, искрящееся множеством мелких пузырьков, имеющее нежный цветочно-фруктовый аромат и свежий вкус с душистым, привлекательным послевкусием. Благодаря универсальному характеру, игристое вино станет не только восхитительным аперитивом, но и составит пару широкому спектру блюд. Абрау-Дюрсо, Брют — одно из лучших российских игристых вин. Оно произведено мастерами Русского Шампанского Дома Абрау-Дюрсо по французской технологии методом Шарма из купажа тщательно отобранного винограда. Метод Шарма был разработан в Италии директором института энологии города Асти Федерико Мартинотти. Особенность технологии заключается в проведении вторичной ферментации в больших герметичных цистернах, после чего вино фильтруется, стабилизируется и разливается под давлением в отдельные бутылки. Вино имеет неограниченный срок хранения, в зависимости от длительности выдержки крепость вина может колебаться от 10,5 до 12,5%.', 'Абрау-Дюрсо', 83.5, 'Брют',
    NULL, NULL, 'Абрау Дюрсо Удельное ведомтсво брют.webp', 'catalog/Абрау Дюрсо Удельное ведомтсво брют.webp',
    1.20, 2.20, 3.80, 4.20,
    '[]'::jsonb, '[]'::jsonb, 0.60
) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
    color_desc = EXCLUDED.color_desc,
