INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'b2df7f55-3e60-4c71-b6fc-c370b0c05e79', NOW(), NOW(), 'abrau-dyurso-victor-dravigny-bryut', 'Абрау-Дюрсо Victor Dravigny брют', 'Белое', 'Золотистый', 'Кубань',
    '["Пино Блан", "Рислинг", "Шардоне"]'::jsonb, 'Вино игристое Абрау-Дюрсо Victor Dravigny белое брют, 0.75л отличается минимальным содержанием сахара. Продукт изготовлен из винограда белых сортов (шардоне, совиньон, пино-блан, пино-нуар). Плоды выращены в виноградниках с уникальным мягким климатом и почвами, богатыми природными элементами. Это позволяет получить приятный напиток с легким фруктовым вкусом с нотками лайма. Послевкусие у него приятное гармоничное. Цвет напитка мягкий, красивый, оттенка спелой пшеницы. Дополнительную золотистость ему придает игра пузырьков, которые лучше всего раскрываются в высоких бокалах. Напиток обладает притягательным ароматом винограда с нотками цитрусовых. Он хорошо утоляет жажду в жаркие дни и создает атмосферу праздника в любое время года. Брют прекрасно сочетается с рыбой и морепродуктами, такими как устрицы, мидии, осьминоги, креветки. Его можно подать к столу и с блюдами из белой птицы. Фрукты тоже способны удачно дополнить вкус напитка. Шампанское следует подавать к столу охлажденным, но не замороженным. Для этого заблаговременно его помещают в камеру холодильника или другое прохладное место. Бутылку с игристым вином также можно опустить в ведерко, наполненное водой со льдом. Алкогольный напиток принято пить из длинных бокалов, сделанных из прозрачного стекла.', 'Абрау-Дюрсо', 83.5, 'Брют',
    NULL, NULL, 'Абрау Дюрсо Виктор Дравиньи брют.webp', 'catalog/Абрау Дюрсо Виктор Дравиньи брют.webp',
    1.20, 2.20, 3.80, 4.20,
    '["лайм"]'::jsonb, '[]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
