INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'e5f80abb-fe8f-4c0f-91fb-5a61a3499f07', NOW(), NOW(), 'aristov-anima-millesimato-beloe-bryut', 'Аристов ANIMA Millesimato белое брют', 'Белое', 'Светло-соломенный', 'Кубань',
    '["Алиготе", "Мюллер-Тургау", "Пино Блан", "Рислинг", "Шардоне"]'::jsonb, 'Светло-соломенный цвет игристого Aristov Anima Millesimato, с бледными оттенками жёлтого золота, подчеркивает его непревзойденную красоту, а игра пузырьков создаёт атмосферу торжественности. Развитый аромат, соответствующий сортовому составу, наполняет пространство нюансами зеленых фруктов и минеральности. Настоящее волшебство скрывается в гармоничном вкусе, отличающимся чистотой и ясностью, без тонов окисленности. Anima Millesimato - идеальное сочетание свежести и изысканности, которое подарит истинное удовольствие ценителям игристых вин. Освежающее игристое вино, идеальный тандем легкости и изысканности, истинное удовольствие для ценителей игристых напитков. Для изготовления игристого вина используется виноград сортов Шардоне, Алиготе и Пино Белый, собранный механизированным способом, а также Мюллер-Тургау и Рислинг Рейнский, собранный частично вручную. Сбор винограда проводится с разновозрастных лоз по достижении ягодами оптимальной сахаристости (16-18%). На винодельне виноград проходит мягкое прессование, настолько бережное, чтобы не экстрагировать полифенолы из кожицы винограда. Далее сусло осветляется путем флотации. Ферментация осуществляется при контролируемой температуре 16-18С в стальных чанах. Перед вторичным брожением базовые вина смешиваются в точно выверенных пропорциях для достижения идеального баланса и яркого выражения особенностей вкуса и аромата каждого из сортов. Вторичная ферментация проводится в акратофоре в течение 28 дней. Выдержка на тонком осадке длится не менее 2 месяцев, за это время игристое вино приобретает особенно соблазнительную глубину.', 'Кубань-Вино', 83.5, 'Брют',
    NULL, NULL, 'Аристов Анима милезимиато брют.webp', 'catalog/Аристов Анима милезимиато брют.webp',
    1.20, 2.20, 4.50, 1.10,
    '["кожа", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
