    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '937f3aa1-5049-4ff1-8109-36054bf3ae1e', NOW(), NOW(), 'di-kaspiko-di-caspico-fiori-di-mare-verde', 'Ди Каспико (Di Caspico Fiori di Mare Verde)', 'Белое', 'Светло-соломенный', 'Дагестан',
    '["Августин", "Бианка", "Первенец Магарача"]'::jsonb, 'Di Caspico Fiori di Mare — лёгкое сухое вино с освежающим характером и тонкой природной гармонией, навеянное морским бризом и мягкой прохладой прибрежных виноградников.


В бокале — светлый оттенок с едва заметным зеленоватым отблеском, подчёркивающий свежесть и чистоту стиля. Визуально вино создаёт ощущение лёгкости и прозрачности, словно отражение солнечного света на воде.


Аромат раскрывается деликатно и свежо: в нем переплетаются цитрусово-фруктовые ноты с легкими травянистыми оттенками, создавая живой и сбалансированный букет.


Во вкусе вино яркое и освежающее, с цветочными нюансами и нотами белых фруктов. Приятная кислинка придаёт ему живость и делает вкус гармоничным, переходящим в мягкое и чистое послевкусие.


Fiori di Mare прекрасно сочетается с рыбой, морепродуктами, белым мясом, свежими салатами и мягкими сырами, подчеркивая их деликатность и добавляя свежие акценты.


Это вино — идеальный выбор для тёплых дней и легких встреч, когда хочется ощутить свежесть, свободу и атмосферу беззаботного отдыха у моря.', 'Дербент Вино', 83.5, 'Сухое',
    NULL, NULL, 'FDM_verde_white.webp', 'catalog/FDM_verde_white.webp',
    1.20, 2.20, 4.50, 1.30,
    '[]'::jsonb, '[]'::jsonb, 0.60
) ON CONFLICT (slug) DO UPDATE SET
