    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '37b9b51d-325b-47d4-91fc-133df3efb502', NOW(), NOW(), 'igristoe-vino-bryut-beloe-di-caspico', 'Игристое вино брют белое Di Caspico', 'Белое', 'Лимонный с золотистыми бликами', 'Дагестан',
    '["Алиготе", "Рислинг", "Шардоне"]'::jsonb, 'Di Caspico брют белое — игристое вино с бодрым, свежим характером и лёгким южным настроением Каспийского побережья.  
В его основе — гармоничный купаж сортов Первенец Магарача, Ркацители и Совиньон Блан, который формирует чистый, элегантный профиль и подчёркивает природную яркость вина. Светло-соломенный цвет с блестящими отблесками и тонкая игра пузырьков добавляют ощущение живости и праздника.  
Аромат раскрывается нотами зелёного яблока, цитрусов и белых цветов, дополняясь лёгкими фруктовыми нюансами. Во вкусе — сухое, собранное и освежающее: аккуратная кислотность, выраженные фруктовые акценты и чистое, долгое послевкусие с приятной пикантной свежестью.  
Di Caspico брют белое — отличный выбор для аперитива, морепродуктов и лёгких закусок, а также для встреч, где важны лёгкость, стиль и настроение.', 'Дербент Вино', 83.5, 'Брют',
    NULL, NULL, 'ДК_бел_брют.webp', 'catalog/ДК_бел_брют.webp',
    1.20, 2.20, 4.50, 1.30,
    '["яблоко", "белые цветы"]'::jsonb, '[]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
