INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '25dba3c2-5923-4940-bb82-6672e006eb94', NOW(), NOW(), 'kaberne-sovinon-1', 'Каберне Совиньон', 'Красное', 'Глубокий рубиновый', 'Кубань',
    '["Каберне Совиньон"]'::jsonb, 'Аромат: оттенки кофе, ванили и специй. Яркие нюансы ферментированного табачного листа и спелой чёрной черешни.

Вкус: с мощными и спелыми танинами, отличной кислотностью и яркой фруктовостью. Гармоничное и сбалансированное, с прекрасной перспективой для бутылочной выдержки.

Особенность винификации

Ручной сбор. Двойная инспекция ягод. Деликатное гребнеотделение с получением целых ягод. Предферментационная мацерация в течение 5 дней при температуре 8 градусов Цельсия. Техника винификации — комбинация ремонтажа и деликатного переворачивания «шапки» специальной боковой мешалкой. Брожение в стальном винификаторе при температуре 30 градусов Цельсия — 6 дней, с последующей постферментационной мацерацией. Общая продолжительность скин-контакта — 25 дней. Полная малолактика. Выдержка в барриках из французского, кавказского, американского и иберийского дуба в течение 12 месяцев — 2/3 от общего объёма. 1/3 от общего объёма 12 месяцев выдерживаются в новых тонно из французского дуба объёмом 500 литров. Ассамбляж. Кларификация. Стабилизация тартратов. Розлив с применением инертного газа и вакуумирования.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'каб сов.webp', 'catalog/каб сов.webp',
    1.20, 2.80, 3.00, 1.10,
    '["черешня", "дуб", "ваниль", "кофе", "табак"]'::jsonb, '["ваниль", "кофе", "табак"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
