INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '928b8404-986d-4655-80c5-0f6df0763f12', NOW(), NOW(), 'kaberne-sovinon-appasimento', 'Каберне Совиньон Appassimento', 'Красное', 'Глубокий рубиновый', 'Кубань',
    '["Каберне Совиньон"]'::jsonb, 'Аромат: необычайно сложный и концентрированный, преобладают оттенки кофе, шоколада, вишневой пастилы, джема из черных лесных ягод, лакричной карамели и восточных специй. Дополняют палитру ароматов благородные бальзамические ноты.

Вкус: невероятно рельефный ягодный, вино плотное, но при этом абсолютно сбалансированное. Длительное послевкусие с оттенками подлеска, сладких фиников и засахаренного инжира.

Особенность винификации

Каберне Совиньон с отдельного парцеля на Западном склоне Лысой Горы заизюмливается на лозе в финальной стадии созревания. После уборки грозди дополнительно подсушиваются в специальных кассетных ящиках под навесом винодельни. Увяливание проходило в течение 14 дней. После деликатного гребнеотделения провели холодное настаивание мезги в течение 7 дней при t 8 С. Медленное брожение осуществлялось в стальных винификаторах, длительностью 20 дней при t 25 С. Техника винификации – деликатный ремонтаж. Постферментационная мацерация – 14 дней. Общий скин-контакт – 41 день. Прессование, потом первичное осветление и переливка в бочки тонно из французского дуба, из которых 20% - новые, а остальные 80%–2, 3, 4 пассажей. Выдержка в тонно – 3 года, затем переливка в дубовые буты, объемом 3000 литров. Выдержка в бутах – 1 год. Деликатная кларификация и розлив без фильтрации в декабре 2024. Дополнительная выдержка в бутылках – 10 месяцев.', 'Галицкий и Галицкий', 83.5, NULL,
