    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '3563aad5-69e5-4d9d-9731-939f612562e1', NOW(), NOW(), 'kokur-avtorskoe', 'Кокур Авторское', 'Белое', 'Соломенный с золотистыми переливами', 'Крым',
    '["Кокур Белый"]'::jsonb, 'В аромате сочетаются пряные нотки полевых цветов и спелых фруктов, создавая гармоничную цветочно-медовую композицию с лёгким оттенком груши.

Полный и пряный вкус раскрывает всю ароматическую палитру, плавно переходя в гармоничную горчинку в послевкусии.

Виноград собирается вручную при сахаристости не менее 20%. После отделения гребней и охлаждения виноград направляется на прессование в пневматический процесс. Далее сусло-самотек и сусло первой фракции отправляется на брожение, которое длится при контролируемой температуре 15-20 дней. Определённые этапы производства протекают в инертной среде.', 'Массандра', 83.5, NULL,
    NULL, NULL, '4287_YChPNz3-no-bg-preview (carve.photos).webp', 'catalog/4287_YChPNz3-no-bg-preview (carve.photos).webp',
