INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'cdac93ea-9a48-49a8-9252-a6811cdedd49', NOW(), NOW(), 'kokur-premium', 'Кокур Премиум', 'Белое', 'Соломенный с золотистыми переливами', 'Крым',
    '["Кокур Белый"]'::jsonb, 'Яркий аромат с доминантой цветочно-медовых нот акации, крымского разнотравья и лимонника.

Вкус изысканный, свежий и сбалансированный, с оттенками крыжовника, алычи и белой смородины. Послевкусие продолжительное, с переливами фруктовых нот и легкой минеральностью.

Виноград собран вручную. Мягко переработан на современном пневматическом прессе. Медленное брожение в нержавеющих емкостях при низких температурах и выдержка на тонком осадке.

Автор гида «Российские вина» Артур Саркисян, присудив этому вино «золото», так описал это вино: «Аромат яркий, комплексный, с доминантой цветочных нот акации, луговых трав, лимонника, легким тоном эвкалипта. Во вкусе элегантное, свежее, гармоничное, с комплексом оттенков крыжовника, алычи, белой смородины. Послевкусие долгое, с переливами фруктовых и минеральных тонов».', 'Массандра', 83.5, NULL,
    NULL, NULL, '4291_pifLuYu-no-bg-preview (carve.photos).webp', 'catalog/4291_pifLuYu-no-bg-preview (carve.photos).webp',
    1.20, 2.20, 4.50, 4.20,
    '["мед", "лимон", "акация", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
