INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '72e59652-ad33-4451-b633-f0b3d0a178f7', NOW(), NOW(), 'krasnostop-zolotovskij', 'Красностоп Золотовский', 'Красное', 'Глубокий рубиновый', 'Кубань',
    '["Красностоп Золотовский"]'::jsonb, 'Аромат: кофе мокко, тёмный шоколад, терново-черносливовые оттенки, кожаное седло и лакрица.

Вкус: объёмное тело, мощные спелые танины обещают вину долгое поступательное развитие в бутылке. Преобладающие оттенки вкуса: чернослив, ежевика, сочная вишня. Долгий финиш с кофейно-сливочным оттенком, тёплый за счет высокой спиртуозности.

Особенность винификации

Ручная уборка в последних числах сентября. В этот момент ягоды заизюмлены на лозе на 60%. 2/3 винограда направляются на винификацию. 1/3 — на дополнительное подвяливание в кассетных ящиках с перфорацией. Увяливание происходит в течение 3-х недель на открытом воздухе под навесом и на ветру, в абсолютно естественных условиях — классическая технология апассименто. 2/3 винограда, который сразу после уборки направился на винификацию: деликатное гребнеотделение, без дробления ягоды. Перемещаем в винификатор и делаем холодное настаивание в течение 4-х суток при температуре 3–5 градусов Цельсия. Затем поднимаем температуру до 25 градусов Цельсия, задаём дрожжи — штамм специально селекционированный для Амароне. Брожение при температуре 29–30 градусов Цельсия. Техники винификации: комбинация деликатного медленного ворошения шапки специальной встроенной в винификатор лопастью и ремонтаж. После завершения брожения, которое длится 9 дней, проводим постферментационную мацерацию. Общий скин-контакт более 20 дней. Деликатное лёгкое прессование, осветление и залив в новые 500-литровые тонно из французского дуба. Малолактика в тонно. Выдержка в тонно 2 года. Кларификация — свежий альбумин из яиц домашней курицы. Деликатная фильтрация. Розлив в бутылку с применением инертного газа и вакуумирования. Выдержка в бутылке 1 год. С виноградом, оставленным на естественное увяливание на воздухе — всё то же, но задаётся гипперконцентрация дрожжей, чтобы запустить брожение.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'красностоп.webp', 'catalog/красностоп.webp',
    1.20, 2.80, 3.00, 4.20,
    '["вишня", "ежевика", "чернослив", "мед", "дуб", "шоколад", "кофе", "кожа"]'::jsonb, '["шоколад", "кофе"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
