INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '1de14a65-ee44-49cf-8de7-fb1d38e666ed', NOW(), NOW(), 'lesnaya-proseka', 'Лесная просека', 'Белое', 'Светло-золотистый', 'Кубань',
    '["Алиготе", "Пино Блан", "Шардоне"]'::jsonb, '«Лесная Просека» от Aristov Arte — лёгкое, свежее и гастрономичное игристое брют, созданное главным энологом Артемом Васильевым как «питкий» купаж ароматных белых сортов (Шардоне, Пино Блан и Алиготе) без амбиций стать «российским просекко», но точно попавшее в настроение и стиль потребления современной аудитории. Вино производится методом вторичного брожения в резервуарах с выдержкой на тонком дрожжевом осадке, что обеспечивает чистоту вкуса и аккуратную глубину.

В бокале оно светло-соломенное с зелено-золотистыми отблесками; в аромате играют белые фрукты, лёгкие цветочные нюансы и тонкая минеральность, а во вкусе — живое, бодрящее игристое с деликатной колкостью и продолжительным минеральным послевкусием. Оптимальная температура подачи — 5–7°C; отлично работает как аперитив и в паре с лёгкими закусками: тартаром из рыбы, устрицами, салатами с цитрусовой заправкой, мягкими козьими сырами.', 'Кубань-Вино', 83.5, 'Брют',
    NULL, NULL, 'Screenshot_4.webp', 'catalog/Screenshot_4.webp',
    1.20, 2.20, 4.50, 4.20,
    '["минералы"]'::jsonb, '["минералы"]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
    color_desc = EXCLUDED.color_desc,
    region = EXCLUDED.region,
    grape_varieties = EXCLUDED.grape_varieties,
