INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '34d460ac-d689-4065-91e8-9ed87de72fc3', NOW(), NOW(), 'merlo', 'Мерло', 'Красное', 'Рубиновый', 'Кубань',
    '["Мерло"]'::jsonb, 'Аромат: переплетены яркие оттенки чёрных ягод: ежевики, шелковицы, кожи и специй, а также чернослива с легким «дымком».

Вкус: полнотелое, многослойное, со спелыми и упругими танинами, интегрированным дубом и богатой ягодной палитрой. Долгое послевкусие с нюансами ванили, чёрных ягод и благородного французского дуба. 

Особенность винификации

Ручной сбор. Двойная инспекция ягод. Деликатное гребнеотделение с получением целых ягод. Предферментационная мацерация в течение 6 дней при температуре 8 градусов Цельсия. Техника винификации — комбинация ремонтажа и деликатного переворачивания «шапки» специальной боковой мешалкой. Брожение в стальном винификаторе при температуре 30 градусов Цельсия — 7 дней, с последующей постферментационной мацерацией. Общая продолжительность скин-контакта — 22 дня. Полная малолактика. Выдержка в новых тонно объёмом 500 литров из французского дуба в течение 12 месяцев — 2/3 от общего объёма. Оставшиеся 1/3 от общего объёма 12 месяцев выдерживаются в новых барриках из французского дуба объёмом 225 литров. Ассамбляж. Кларификация. Стабилизация тартратов. Розлив с применением инертного газа и вакуумирования.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'мерло.webp', 'catalog/мерло.webp',
    1.20, 4.60, 3.00, 1.10,
    '["ежевика", "чернослив", "дуб", "ваниль", "кожа"]'::jsonb, '["ваниль"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
