    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'd65acffe-1e35-4e1f-a032-51a562be018e', NOW(), NOW(), 'alma-valley-merlo-rezerv-krasnoe-suhoe-14', 'Мерло Резерв', 'Красное', 'Вино глубокого рубинового цвета.', 'Крым',
    '["Мерло"]'::jsonb, 'Изящный аромат соткан из нот ежевики, черешни, терна, инжира и вяленой вишни с тонкими штрихами шоколада и пряностей. Вкус полный, играющий, с живой кислотностью и мягкими танинами с идеально интегрированной бочкой. В финале тон сушеных ягод и темного шоколада. Красивое и зрелое вино для тихого удовльствия истинного гедониста. Можно пить сейчас или подержать еще год-два для смягчения танинов. Перед подачей аэрировать.', 'Alma Valley', 83.5, NULL,
    NULL, NULL, 'alma-valley-merlo-rezerv-krasnoe-suhoe-vyderzhannoe-14.webp', 'catalog/alma-valley-merlo-rezerv-krasnoe-suhoe-vyderzhannoe-14.webp',
