INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'bee7a62e-9c8d-4e4f-9453-75db516786f6', NOW(), NOW(), 'muskat-pozdnego-sbora-rozovyj', 'Мускат позднего сбора розовый', 'Розовое', 'Нежно-розовое', 'Крым',
    '["Мускат Розовый"]'::jsonb, '«Мускат позднего сбора» розовое
Сладкое розовое вино ЗГУ Крым
Золото
Золото
5
Серебро
Серебро
4
Бронза
Бронза
5
Все награды
Сладкое вино из сорта Мускат розовый – легенда виноделия Южного берега Крыма. Вина из винограда, собранного в конце октября или начале ноября, создавались в «Алупке» и «Гурзуфе». Стилистика уникального вина была воссоздана в урожаях начиная с 2016 года на массандровской винодельне «Гурзуф».

Виноград собирают при высоком уровне сахаристости, в частично заизюмленном виде. Благодаря высокому содержанию сахара сусло получается тягучим, как мёд. Брожение осуществляется при низких температурах, что позволяет сохранить яркую ароматику, а для сохранения высокой остаточной сахаристости практикуется остановка брожения холодом.

Вино нежно-розового цвета с легким персиковым оттенком. В аромате сложная гамма цветочных и фруктовых тонов, цветущего розового сада. Во вкусе гармоничное, округлое, с оттенком варенья из лепестков розы, малинового конфитюра, спелых красных садовых ягод, деликатное послевкусие с нотами барбариса.

Виноград собирается вручную в частично подвяленном виде при сахаристости в ягоде не ниже 31%. Брожение осуществляется при низких температурах, что позволяет сохранить яркую ароматику. Остановка брожения осуществляется холодом для сохранения остаточной сахаристости.', 'Массандра', 83.5, 'Сладкое',
    NULL, NULL, '4290_zDKbOVA-no-bg-preview (carve.photos).webp', 'catalog/4290_zDKbOVA-no-bg-preview (carve.photos).webp',
    4.50, 2.40, 3.20, 4.20,
    '["малина", "персик", "роза"]'::jsonb, '[]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
