INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '381493ae-76be-47c2-985e-14818606e352', NOW(), NOW(), 'muskat-avtorskoe-vino', 'Мускат. Авторское вино', 'Белое', 'Светло-соломенный', 'Крым',
    '["Мускат Белый"]'::jsonb, 'Это вино отличают типичные для данного терруара тонкие цитрусовые нотки, дополненные яркими оттенками муската и тропических фруктов.

В округлом, хорошо сбалансированном вкусе раскрываются нотки лимонного сорбета и цукатов. В послевкусии прослеживаются лёгкие минеральные нюансы.

Виноград собирается вручную при сахаристости не менее 20%. После отделения гребней и охлаждения виноград направляется на прессование в пневматический процесс. Далее сусло-самотек и сусло первой фракции отправляется на брожение, которое длится при контролируемой температуре 15-20 дней. Определённые этапы производства протекают в инертной среде.

«Мускат» Авторское вино выдерживается в течение 2-4 месяцев на тонком дрожжевом осадке в стальных емкостях, что придает ему утончённый органолептический профиль.', 'Массандра', 83.5, NULL,
    NULL, NULL, '2923_GVAPsCA-no-bg-preview (carve.photos).webp', 'catalog/2923_GVAPsCA-no-bg-preview (carve.photos).webp',
    1.20, 2.20, 4.50, 1.10,
    '["цукаты", "лимон", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
