) VALUES (
    '40ddebb2-8b78-432f-95ad-bd881c830d20', NOW(), NOW(), 'myshako-igristoe-beloe-bryut', 'Мысхако игристое белое брют', 'Белое', 'Светло-соломенный с зеленоватым оттенком', 'Кубань',
    '["Алиготе", "Шардоне"]'::jsonb, 'Гармоничный аромат вина раскрывается оттенками цветов винограда. Вкус многогранный, наполнен нотками винограда, груши и яблока. Вино является прекрасным аперитивом, хорошо сочетается с морепродуктами, белым мясом, ризотто и рыбными блюдами. Это новинка компании Мысхако, освежающее белое игристое вино из линейки Квинтэссенция, созданное из винограда сорта Совиньон Блан, который выращивается в защищенном географическом регионе Кубань. По окончании сбора урожая плоды подвергаются традиционной винификации при контролируемой температуре в стальных чанах. В дальнейшем игристое вино производится в соответствии с итальянским методом Шарма, который предполагает проведение вторичной ферментации в герметичных автоклавах, где полученное ранее базовое вино бродит с сахаром и дрожжами. Игристое вино идеально в качестве аперитива, а также в паре с легкими блюдами и закусками, рыбой, морепродуктами, устрицами, белым мясом под нежным соусом.', 'Мысхако', 83.5, 'Брют',
    NULL, NULL, 'Мысхако игристое брют белое.webp', 'catalog/Мысхако игристое брют белое.webp',
    1.20, 2.20, 4.50, 1.10,
    '["яблоко", "груша"]'::jsonb, '[]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
