INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '69f35dde-6169-485e-963e-7bc6c0e7b86b', NOW(), NOW(), 'pino-gri-avtorskoe', 'Пино Гри Авторское', 'Белое', 'Светло-соломенный', 'Крым',
    '["Пино Гри"]'::jsonb, 'Аромат яркий и многослойный, в котором чувствуются тона спелого яблока и груши, а также акценты экзотических фруктов и легкая леденцовая нотка.

Гармоничный вкус раскрывается фруктовыми нотами, сочетающимися с мягкой кислотностью, которая идеально сбалансирована.

Виноград собирается вручную при сахаристости не менее 20%. После отделения гребней и охлаждения виноград направляется на прессование в пневматический процесс. Далее сусло-самотек и сусло первой фракции отправляется на брожение, которое длится при контролируемой температуре 15-20 дней. Определённые этапы производства протекают в инертной среде.

«Пино Гри» Авторское вино выдерживается в течение 2-4 месяцев на тонком дрожжевом осадке в стальных емкостях, что придает ему утончённый органолептический профиль.', 'Массандра', 83.5, NULL,
    NULL, NULL, '4286_IxmFMpd-no-bg-preview (carve.photos).webp', 'catalog/4286_IxmFMpd-no-bg-preview (carve.photos).webp',
    1.20, 2.20, 3.80, 1.10,
    '["яблоко", "груша"]'::jsonb, '[]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
