INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'cdc123e0-6ecf-4ad6-b9c5-2d67794ce0cf', NOW(), NOW(), 'pino-nuar-dzhavaga', 'Пино Нуар Джавага', 'Красное', 'Рубиновый', 'Кубань',
    '["Пино Нуар"]'::jsonb, 'Аромат: раскрывается оттенками фиалок и пряных трав, нотами спелой вишни и сушеной малины, а также тонкими нюансами дробленных камней, благородных пород дерева, пряностей.

Вкус: объемное, структурное, с изысканными танинами и живой кислотностью. Послевкусие длительное с пряно-фруктовым финишем.

Особенность винификации

Ручной сбор винограда 27 сентября. Охлаждение винограда. Двойная инспекция ягод. Деликатное гребнеотделение с получением целых ягод. Предферментационная мацерация в течение 7 дней, при температуре 8 градусов Цельсия. Техника винификации: комбинация пижажа и ремонтажа. Спонтанное брожение в стальном винификаторе, с последующей постферментационной мацерацией. Использовано 30% гребней. Общая продолжительность скин-контакта — 25 дней. Полная малолактика, выдержка в дубовых бочках более 15 месяцев, из них 70% - бургундские пьесы, объемом 228 л - новые, 2-го и 3-го пассажа, остальные 30% - выдержка в бутах. Ассамбляж. Кларификация. Стабилизация тартратов. Розлив с применением инертного газа и вакуумирования.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'пино нуар джавага.webp', 'catalog/пино нуар джавага.webp',
    1.20, 2.80, 3.00, 1.10,
    '["вишня", "малина", "дуб"]'::jsonb, '[]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
