INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'c2944ea0-ef11-490b-b6ad-107a14df57e3', NOW(), NOW(), 'risling', 'Рислинг', 'Белое', 'Серебристо-соломенный', 'Кубань',
    '["Рислинг"]'::jsonb, 'Аромат: элегантный и свежий, с обилием цитрусовых нюансов и весенних цветов, с деликатным намёком на пчелиный воск и мёд, а также с лёгкими петрольными нотами.

Вкус: тонкое, изящное тело, пронзительная и гармоничная кислотность с долгим послевкусием и яркой минеральностью.

Особенность винификации

Ручной сбор. Охлаждение винограда. Инспекция гроздей. Гребнеотделение с последующим дроблением ягоды. Криомацерация в прессе в течение 4 часов. Отбор самотёка и деликатное прессование в атмосфере азота. Стабуляж в течение 14 дней при температуре 2 градуса Цельсия. Брожение сусла в течение 14 дней при температуре 18–19 градусов Цельсия. Сталь — 100%. Регулярный баттонаж в течение 11 месяцев. Ассамбляж. Кларификация. Стабилизация тартратов. Розлив с применением инертного газа и вакуумирования.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'рислинг.webp', 'catalog/рислинг.webp',
    1.20, 1.60, 4.50, 1.10,
    '["минералы"]'::jsonb, '["минералы"]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
    color_desc = EXCLUDED.color_desc,
    region = EXCLUDED.region,
    grape_varieties = EXCLUDED.grape_varieties,
