INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'e177f135-af4c-473b-b2be-0b9841023c89', NOW(), NOW(), 'roze-1', 'Розе', 'Розовое', 'Светло-розовый с лососевым оттенком и блеском', 'Кубань',
    '["Каберне Совиньон", "Мерло", "Пино Нуар"]'::jsonb, 'Аромат: чистый и свежий, с нюансами клубники, малины и белой смородины.

Вкус: звонкий и лёгкий, с оттенками садовых ягод, освежающей кислотностью и ярким финишем. 

Особенность винификации

Ручной сбор каждого сорта по отдельности. Охлаждение винограда до +5 градусов Цельсия. Инспекция гроздей. Раздельная переработка. Гребнеотделение с последующим деликатным дроблением ягод. Холодная мацерация в прессе в течение 2 часов. Отбор самотёка и деликатное прессование в атмосфере азота. Стабуляж — 50% объёма, в течение 15 дней при температуре 2 градуса Цельсия. Продолжительность брожения — 15 дней при температуре 16–17 градусов Цельсия. Выдержка 8 месяцев на тонком дрожжевом осадке, без баттонажа. Ассамбляж. Кларификация. Стабилизация тартратов. Розлив с применением инертного газа и вакуумирования.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'розе.webp', 'catalog/розе.webp',
    1.20, 2.40, 3.20, 4.20,
    '["малина", "клубника"]'::jsonb, '[]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
