    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '9ca4761c-44cb-469a-99fa-765eddce2a0c', NOW(), NOW(), 'roze-avtorskoe-vino', 'Розе. Авторское вино', 'Розовое', 'Лососевый', 'Крым',
    '["Сира"]'::jsonb, 'Яркий аромат с оттенками клубники, земляники и красной смородины.

Гармоничный и свежий вкус с нежным ягодным оттенком и сливочным послевкусием.

Сортовой состав: Сира, Каберне Совиньон

Первое сухое розовое вино в Авторской линейке «Массандры» создано виноделом Игорем Шпилем на исторической винодельне в Гурзуфе. Работая с сортами для создания красных вин линейки, Игорь Шпиль применил для части винограда специальную технологию переработки по белому способу: с минимальным настоем сока красных сортов на мезге в процессе медленного прессования. В результате получилось самое яркое летнее вино линейки.

Виноград для производства вина собирают только вручную и бережно перерабатывают. Ферментация протекает в нейтральных емкостях из нержавеющей стали при контролируемых температурах, что обеспечивает яркую фруктовую ароматику, присущую сорту, а дальнейшая выдержка на тонком дрожжевом осадке в течение нескольких месяцев придает вину утончённый органолептический профиль.', 'Массандра', 83.5, 'Сухое',
    NULL, NULL, '2922_lCf6Bdm.webp', 'catalog/2922_lCf6Bdm.webp',
    1.20, 2.40, 3.20, 1.10,
    '["клубника", "земляника", "мед"]'::jsonb, '[]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
