INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'ebcb920e-ddd3-4180-ade0-595303eb3775', NOW(), NOW(), 'solnechnaya-dolina-meganom-kokur-beloe-bryut', 'Солнечная Долина Меганом Кокур белое брют', 'Белое', 'Светло-золотистый', 'Крым',
    '["Кокур"]'::jsonb, 'Игристое выражение самого известного крымского белого автохтона Кокур - уже интересно. А если добавить к этому классический метод производства и уникальность терруара Солнечной Долины - вино становится совершенно уникальным! Оно несомненно является отличным аперитивом, но и в гастрономическом плане обладает массой достоинств. 
Цвет вина: Светло-золотистый. Устойчивый, мелкий бисерный перляж. 
Букет: Довольно сложный аромат с преобладающими оттенками свежих фруктов, леденцово-карамельнымии и цитрусовыми оттенками, а также минеральными нюансами. 
Вкус: Яркий вкус с тонами южных фруктов. В балансе акцентировано внимание на свежую кислотность. Послевкусие вина длительное, развивающееся из фруктовой мягкости в свежесть. 
Гастрономия: Это игристое вино, прежде всего, является замечательным аперитивом. При подборе правильных гастрономических сочетаний стоит обратить внимание на фруктовые блюда и закуски, а также на морепродукты и не сладкую выпечку. Уверены, что его сочетание с молодыми сырами тоже вам понравится.', 'Солнечная долина', 83.5, 'Брют',
    NULL, NULL, 'Солнечная Долина меганом кокур.webp', 'catalog/Солнечная Долина меганом кокур.webp',
    1.20, 2.20, 4.50, 4.20,
    '["минералы"]'::jsonb, '["минералы"]'::jsonb, 0.85
) ON CONFLICT (slug) DO UPDATE SET
