INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    '7672a234-df3c-4ad3-a880-28251c2e87d7', NOW(), NOW(), 'shardone-2', 'Шардоне', 'Белое', 'Светло-соломенный', 'Кубань',
    '["Шардоне"]'::jsonb, 'Аромат: богатая палитра, незабываемое переплетение нюансов спелой айвы, жёлтого яблока, цедры цитрусовых с нотками жареных тостов и сливочно-ореховыми оттенками.

Вкус: лёгкая маслянистость, переходящая в яркую и «живую» кислотность, свежесть и минеральность, присущая терруару «Красная Горка», с преобладанием оттенков белых фруктов.

Особенность винификации

Ручной сбор. Охлаждение винограда. Инспекция гроздей. Гребнеотделение с последующим дроблением ягоды. Криомацерация в прессе в течение 4 часов. Отбор самотёка и деликатное прессование в атмосфере азота. Брожение сусла в течение 12 дней при температуре 19–20 градусов Цельсия, 60% от объёма — сталь, 40% от объёма — новые бургундские пьесы изготовленные из французского дуба высокой плотности, объёмом 228 литров. Полная малолактика для объёма, сброженного в дубе. Сталь — без малолактики. Регулярный баттонаж в течение 11 месяцев как для объёмов выдерживаемых в стали, так и для бочек. Ассамбляж. Кларификация. Стабилизация тартратов. Розлив с применением инертного газа и вакуумирования.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'шардо красная горка.webp', 'catalog/шардо красная горка.webp',
    1.20, 2.20, 4.50, 1.10,
    '["яблоко", "айва", "дуб", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
