INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'eae722c3-5b49-4f01-8a66-d61d999a8ecf', NOW(), NOW(), 'shardone-akacziya', 'Шардоне Акация', 'Белое', 'Золотисто-соломенный', 'Кубань',
    '["Шардоне"]'::jsonb, 'Аромат: сухофрукты, мёд, дыня, сухие травы, цукаты из цитрусовых.

Вкус: впечатляющий объём и маслянистость, сочная мякоть спелой печёной груши, приправленной белым перцем, переходящая в яркую и «живую» кислотность. Свежесть и минеральность, присущая терруару «Красная Горка». Долгий, минеральный финиш, с прекрасно интегрированными благородными оттенками дерева акации, нагретого летним солнцем.

Особенность винификации

Ручной сбор 9 сентября. Охлаждение винограда. Инспекция гроздей. Гребнеотделение с последующим частичным дроблением ягоды. Криомацерация в прессе в течение 2 часов. Отбор самотёка и деликатное прессование в атмосфере азота. Брожение сусла в течение 12 дней при температуре 19–20 градусов Цельсия, 50% от объёма — сталь, 50% от объёма — новые бургундские пьесы, изготовленные из древесины венгерской акации высокой плотности, объёмом 228 литров. Полная малолактика для объёма сброженного в бочках из акации. Сталь — без малолактики. Регулярный баттонаж в течение 15 месяцев как для объёмов выдерживаемых в стали, так и для бочек. Ассамбляж. Кларификация. Стабилизация тартратов. Розлив с применением инертного газа и вакуумирования.', 'Галицкий и Галицкий', 83.5, NULL,
    NULL, NULL, 'шардоне акация.webp', 'catalog/шардоне акация.webp',
    1.20, 2.20, 4.50, 1.10,
    '["груша", "цукаты", "акация", "полевые травы", "дуб", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
