) VALUES (
    '34e485d6-6092-42aa-8933-5703098fc6a4', NOW(), NOW(), 'alma-valley-shardone-rezerv-beloe-suhoe-135', 'Шардоне Резерв', 'Белое', 'Золотистый, сияющий цвет с яркими золотыми бликами.', 'Крым',
    '["Шардоне"]'::jsonb, 'Аромат глубокий, густой и зрелый: доминируют тона желтого персика, абрикоса, легкие цитрусовые оттенки и сладкие специи, переплетающиеся с дымной вуалью. Фоном звучит нота варенья из белой черешни с шафраном и оттенки тоста со сливочно-фруктовым кремом. Вкус округлый, полнотелый, с маслянистой текстурой, умеренной кислотностью и продолжительным послевкусием, где угадывается легкая дымность. Фактурное и самодостаточное вино.', 'Alma Valley', 83.5, NULL,
    NULL, NULL, 'alma-valley-shardone-rezerv-beloe-suhoe-vyderzhannoe-135.webp', 'catalog/alma-valley-shardone-rezerv-beloe-suhoe-vyderzhannoe-135.webp',
