INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'd0a4cb29-9b59-4e0c-92f9-cedf9422ec7d', NOW(), NOW(), 'igristoe-vino-endemy-bianka-bryut-beloe', 'Эндемы Бианка брют белое', 'Розовое', 'Нежно-розовый', 'Дагестан',
    '["Бианка"]'::jsonb, 'Эндемы Бианка — моносортовое вино, отражающее природную гармонию и мягкий характер уникального сорта в его аутентичном звучании.

В бокале — светлый соломенно-золотистый оттенок с прозрачным блеском, подчёркивающим чистоту стиля. Аромат деликатный и многослойный: раскрываются ноты спелого яблока и груши, белой сливы и луговых цветов, дополненные тонкими медовыми и лёгкими ореховыми нюансами.

Во вкусе — мягкость и округлость, свойственные сорту Бианка. Фруктовые оттенки абрикоса и сочной груши гармонично переплетаются с умеренной, освежающей кислотностью. Текстура гладкая, сбалансированная, с аккуратной минеральной линией, переходящей в чистое, спокойное послевкусие с лёгким цветочным акцентом.
На этикетке — образ редкого природного символа региона, подчёркивающий идею эндемичности и уникальности. Бианка, как и истинные природные эндемики, раскрывается особенно ярко в своём родном терруаре, демонстрируя устойчивость, выразительность и природную силу.

Это вино для тех, кто ценит мягкую элегантность, естественную гармонию и честное звучание одного сорта — без лишних акцентов, с вниманием к деталям и уважением к природе.', 'Дербент Вино', 83.5, 'Брют',
    NULL, NULL, 'Эндемы Бианка.webp', 'catalog/Эндемы Бианка.webp',
    1.20, 2.40, 3.20, 1.30,
    '["слива", "яблоко", "груша", "абрикос", "мед", "минералы"]'::jsonb, '["слива", "минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
