INSERT INTO wines (
    id, created_at, updated_at, slug, name, category, color_desc, region,
    grape_varieties, description, winery, roskachestvo_score, sugar_type,
    vintage_year, price_rub, image_filename, image_s3_key,
    sweetness, body, acidity, oak, aroma_tags, flavor_tags, derived_attributes_confidence
) VALUES (
    'f2e57268-482f-408c-95d2-21fce50e2ae4', NOW(), NOW(), 'igristoe-vino-endemy-pino-blan-bryut-beloe', 'Эндемы Пино Блан брют белое', 'Белое', 'Светло лимонный', 'Дагестан',
    '["Пино Блан"]'::jsonb, 'Эндемы Пино Блан Брют — моносортовое игристое вино, отражающее чистоту сорта и благородную сдержанность характера.

В бокале — светло-соломенный цвет с прозрачным блеском и тонкой, живой игрой пузырьков. Аромат деликатный и утончённый: ноты белых цветов, сочной груши и зелёного яблока переплетаются с лёгкими цитрусовыми штрихами. Вкус свежий и гармоничный, с яркой, но мягко интегрированной кислотностью, аккуратной текстурой и оттенками спелых садовых фруктов, переходящих в чистое, минеральное послевкусие. Элегантный перляж подчёркивает природную изысканность вина.

На этикетке — гепард, редкий и стремительный хищник, символ природной силы и грации. Как и этот удивительный эндем, Пино Блан раскрывается точно и стремительно, демонстрируя ясность линии, баланс и внутреннюю энергию в своём чистом моносортовом исполнении.

Это игристое — как мгновение, когда гепард замирает перед рывком: сосредоточенность, красота и совершенство формы. Вино для тех, кто ценит утончённость, характер и живую динамику вкуса.', 'Дербент Вино', 83.5, 'Брют',
    NULL, NULL, 'Эндемы Пино Блан.webp', 'catalog/Эндемы Пино Блан.webp',
    1.20, 2.20, 4.50, 1.30,
    '["яблоко", "груша", "белые цветы", "минералы"]'::jsonb, '["минералы"]'::jsonb, 0.95
) ON CONFLICT (slug) DO UPDATE SET
